import {PRESETS,LIMITS,validateSettings,encodePatch,decodePatch,cppSettings,makeBank} from './engine.js';
const $=id=>document.getElementById(id);let settings={...PRESETS.bark},savedA=null,comparing=false,ctx,node,monitor,analyser,revision=0,updateTimer,sustain=false,midi,selectedInput;const held=new Map(),timers=new Set();
try{const stored=localStorage.getItem('bark-tone-v1');if(stored)settings=decodePatch(stored);}catch{}
const current=()=>comparing?savedA:settings;
const notice=t=>$('notice').textContent=t;
function configure(){clearTimeout(updateTimer);updateTimer=setTimeout(()=>{if(node)node.port.postMessage({type:'configure',bank:makeBank(current(),ctx.sampleRate),revision:++revision});},30);try{localStorage.setItem('bark-tone-v1',encodePatch(settings));}catch{}}
const fields=[['stiffness','ハンマー硬さ',.01,1,''],['damping','減衰',.01,1,''],['cutoff','明るさ',10,1,' Hz'],['drive','音源レベル',.005,1,''],['release_seconds','リリース',.001,1000,' ms'],['pickup_mix','ピックアップ成分',.01,100,'%'],['pickup_gap','ピックアップ距離',.00001,1000,' mm'],['pickup_offset','ピックアップ位置',.00001,1000,' mm'],['volume','プリセット音量',.01,1,'×']];
for(const [key,title,step,scale,unit] of fields){const label=document.createElement('label');label.className='slider';label.textContent=title;const out=document.createElement('output');out.id=`out-${key}`;const input=document.createElement('input');input.type='range';input.id=key;input.min=LIMITS[key][0];input.max=LIMITS[key][1];input.step=step;input.oninput=()=>{settings[key]=+input.value;settings.name='Custom';refresh();configure();};label.append(out,input);$('controls').append(label);}
for(const [key,title] of [['velocity_timbre','ベロシティ音色変化'],['saturate_output','サチュレーション'],['tremolo','トレモロ 4.2 Hz']]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.id=key;input.onchange=()=>{settings[key]=input.checked;settings.name='Custom';refresh();configure();};label.append(input,document.createTextNode(title));$('switches').append(label);}
for(const [id,p] of Object.entries(PRESETS)){const b=document.createElement('button');b.textContent=p.name;b.dataset.preset=id;b.onclick=()=>{comparing=false;settings={...p};refresh();configure();};$('presets').append(b);}
function refresh(){const s=current();for(const [key,,step,scale,unit] of fields){$(key).value=s[key];$(key).disabled=comparing;$(`out-${key}`).textContent=(s[key]*scale).toFixed(scale===1000&&step===.00001?2:step*scale>=1?0:2)+unit;}for(const key of ['velocity_timbre','saturate_output','tremolo']){$(key).checked=s[key];$(key).disabled=comparing;}document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',PRESETS[b.dataset.preset].name===s.name));$('compare').disabled=!savedA;$('compare').textContent=comparing?'Bに戻る':'Aと比較';$('ab-status').textContent=comparing?'Aを試奏中。Bに戻ると調整を続けられます。':savedA?'Aを記憶済み。次の打鍵で比較できます。':'今の音をAに記憶して、調整後の音と比較。';}
async function start(){if(ctx){await ctx.resume();return;}if(!window.AudioContext||!window.AudioWorkletNode)throw Error('AudioWorkletに対応したブラウザで開いてください。');const c=new AudioContext({sampleRate:48000,latencyHint:'interactive'});try{await c.audioWorklet.addModule('./audio-worklet.js');ctx=c;node=new AudioWorkletNode(ctx,'bark-piano',{outputChannelCount:[2]});monitor=ctx.createGain();monitor.gain.value=+$('monitor').value/100;analyser=ctx.createAnalyser();analyser.fftSize=1024;node.connect(analyser).connect(monitor).connect(ctx.destination);node.port.postMessage({type:'configure',bank:makeBank(current(),ctx.sampleRate),revision:++revision});node.port.onmessage=({data:d})=>{if(d.type==='meter'){$('voices').textContent=`${d.voices} / 8 VOICES`;$('reduction').textContent=`LIMITER ${Math.min(0,20*Math.log10(d.gain)).toFixed(1)} dB`;}};node.onprocessorerror=()=>notice('音声処理でエラーが発生しました。ページを再読込してください。');ctx.onstatechange=()=>{$('status').textContent=ctx.state==='running'?`AUDIO ON · ${ctx.sampleRate/1000} kHz`:'AUDIO PAUSED';};await ctx.resume();$('start').textContent='音声を再開';$('status').textContent=`AUDIO ON · ${ctx.sampleRate/1000} kHz`;}catch(e){await c.close();ctx=null;throw e;}}
$('start').onclick=()=>start().catch(e=>notice(e.message));
function post(data){node?.port.postMessage(data);}
function highlight(){document.querySelectorAll('.key').forEach(k=>k.classList.toggle('held',[...held.values()].includes(+k.dataset.note)));}
function on(source,note,velocity=+$('velocity').value){if(!node||ctx.state!=='running'){notice('先に「音を有効にする」を押してください。');return;}if(held.has(source))off(source);held.set(source,note);post({type:'on',note,velocity});highlight();}
function off(source){const note=held.get(source);held.delete(source);if(note!==undefined&&![...held.values()].includes(note))post({type:'off',note});highlight();}
function pedal(value){sustain=value;post({type:'sustain',on:value});$('sustain').setAttribute('aria-pressed',String(value));$('sustain').textContent=`サステイン ${value?'ON':'OFF'}`;}
function panic(){for(const t of timers)clearTimeout(t);timers.clear();held.clear();pedal(false);post({type:'panic'});highlight();}
$('panic').onclick=panic;$('sustain').onclick=()=>pedal(!sustain);window.addEventListener('blur',panic);document.addEventListener('visibilitychange',()=>{if(document.hidden)panic();});
const black=new Set([1,3,6,8,10]);let whites=0;for(let n=48;n<=72;n++){const isBlack=black.has(n%12),k=document.createElement('button');k.className=`key ${isBlack?'black':'white'}`;k.dataset.note=n;k.setAttribute('aria-label',`${['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][n%12]}${Math.floor(n/12)-1}`);if(isBlack)k.style.left=`${whites/15*100-2.1}%`;else{whites++;if(n%12===0)k.textContent=`C${Math.floor(n/12)-1}`;}k.onpointerdown=e=>{e.preventDefault();k.setPointerCapture(e.pointerId);on(`pointer${e.pointerId}`,n);};k.onpointerup=k.onpointercancel=k.onlostpointercapture=e=>off(`pointer${e.pointerId}`);$('keyboard').append(k);}
const keyMap=['KeyA','KeyW','KeyS','KeyE','KeyD','KeyF','KeyT','KeyG','KeyY','KeyH','KeyU','KeyJ','KeyK'];window.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select,[contenteditable=true]'))return;const i=keyMap.indexOf(e.code);if(i>=0){e.preventDefault();on(e.code,60+i);}if(e.code==='Space'&&!e.target.matches('button')){e.preventDefault();pedal(true);}});window.addEventListener('keyup',e=>{if(keyMap.includes(e.code))off(e.code);if(e.code==='Space')pedal(false);});
function later(fn,ms){const t=setTimeout(()=>{timers.delete(t);fn();},ms);timers.add(t);}
$('chord').onclick=()=>{[60,64,67,71].forEach(n=>{on(`demo${n}`,n);later(()=>off(`demo${n}`),900);});};$('compare-velocity').onclick=()=>{panic();[35,80,120].forEach((v,i)=>{later(()=>on('velocity-demo',60,v),i*900);later(()=>off('velocity-demo'),i*900+650);});};$('velocity').oninput=()=>$('velocity-value').value=$('velocity').value;$('monitor').oninput=()=>{$('monitor-value').value=`${$('monitor').value}%`;if(monitor)monitor.gain.setTargetAtTime(+$('monitor').value/100,ctx.currentTime,.02);};
$('remember').onclick=()=>{savedA={...current()};refresh();};$('compare').onclick=()=>{comparing=!comparing;refresh();configure();};
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('save').onclick=()=>download('bark-tone.json',encodePatch(current()),'application/json');$('cpp').onclick=()=>download('bark-tone.h',cppSettings(current()),'text/plain');$('load').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>32768)throw Error('設定ファイルが大きすぎます。');settings=decodePatch(await f.text());comparing=false;refresh();configure();notice('設定を読み込みました。');}catch(e){notice(e.message);}finally{$('file').value='';}};
function chooseMidi(){if(selectedInput)selectedInput.onmidimessage=null;panic();selectedInput=midi.inputs.get($('midi-input').value);if(selectedInput)selectedInput.onmidimessage=({data:[s,n,v]})=>{const type=s&240,channel=s&15;if(type===144&&v>0)on(`midi${channel}:${n}`,n,v);else if(type===128||type===144)off(`midi${channel}:${n}`);else if(type===176&&n===64)pedal(v>=64);else if(type===176&&(n===120||n===123))panic();};}
function listMidi(){const prior=$('midi-input').value;$('midi-input').replaceChildren();for(const input of midi.inputs.values()){const o=document.createElement('option');o.value=input.id;o.textContent=input.name||'MIDI keyboard';$('midi-input').append(o);}if([...midi.inputs.keys()].includes(prior))$('midi-input').value=prior;$('midi-input').hidden=!midi.inputs.size;$('midi-status').textContent=midi.inputs.size?'入力を選び、キーボードを弾いてください。':'接続されたMIDI入力がありません。';chooseMidi();}
$('midi').onclick=async()=>{try{if(!navigator.requestMIDIAccess)throw Error('このブラウザはWeb MIDI非対応です。Chrome等でお試しください。');await start();midi=await navigator.requestMIDIAccess({sysex:false});midi.onstatechange=listMidi;listMidi();}catch(e){$('midi-status').textContent=e.message;}};$('midi-input').onchange=chooseMidi;
const canvas=$('scope'),g=canvas.getContext('2d'),wave=new Float32Array(1024);function draw(){requestAnimationFrame(draw);g.fillStyle='#26392f';g.fillRect(0,0,640,160);g.strokeStyle='#a9bc7f';g.lineWidth=1.5;g.beginPath();if(analyser)analyser.getFloatTimeDomainData(wave);for(let i=0;i<1024;i++){const x=i/1023*640,y=80-wave[i]*72;i?g.lineTo(x,y):g.moveTo(x,y);}g.stroke();}refresh();draw();
